/(instagram|facebook)\s+(biznes\s+)?(hesab[ıi]n[ıi]z|s[əe]hif[əe]niz)[^.]{0,30}(ba[ğg]lanacaq|silin[əe]c[əe]k|bloklanacaq|dayand[ıi]r[ıi]lacaq)/iu

